import{z as s,x as A,o as e,c as d,q as o,j as i,D as E,d as t,s as n,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"目标日期与下滑路径","description":"","frontmatter":{"title":"目标日期与下滑路径","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/target-date-glidepath.md","filePath":"quant/target-date-glidepath.md","lastUpdated":1791413859000}'),p={name:"quant/target-date-glidepath.md"};function m(D,a,h,u,T,C){const r=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=o('<h1 id="目标日期与下滑路径" tabindex="-1">目标日期与下滑路径 <a class="header-anchor" href="#目标日期与下滑路径" aria-label="Permalink to &quot;目标日期与下滑路径&quot;">​</a></h1><div class="epigraph"><p>下滑路径把股权权重写成距退休时间的函数；劳动收入像一只不可交易的债券，年轻时才该更像 Merton 的高股权。</p><footer>—— 对照 Bodie, Merton and Samuelson, Labor Supply Flexibility and Portfolio Choice, JEDC, 1992；目标日期基金实务</footer></div><p><a href="/quant/multi-period-risk-budget">上一课</a>管机构主动预算。目标日期（TDF）的缺口是<strong>生命周期</strong>：人力资本不可交易，金融财富随年龄从「人力资本占优」变成「组合占优」。本课写下滑路径的经济学与实现，不把「100 减年龄」当定理。后课杠杆拖累解释为什么路径上加杠杆 ETF 会偏离设计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Merton 常投资比例在 \\(\\mu,\\sigma,\\gamma\\) 不变时是常数。生命周期里：年轻时人力资本（未来工资）像债券，金融组合应更偏股以平衡总财富；临退休人力资本耗尽，金融组合应降股。Bodie–Merton–Samuelson 把劳动供给弹性也写进去。问题是 TDF 的下滑是<strong>产品规则</strong>，对所有同龄人同一条路径，忽略职业风险（金融从业者的工资与股市正相关，更应少股）与积存水平。</p><p><span class="marginnote">术语翻译：人力资本就是你未来全部工资的贴现值——一个刚工作的年轻人可能有几百万元的人力资本，只是不能拿出来卖。总财富 \\(=\\) 金融财富 \\(+\\) 人力资本；年轻人的大头是那只「看不见的债券」，所以金融账户要多配股票来平衡整个财富组合的风险。</span></p><p>实现：目标日期是组合保险还是战略配置？很多 TDF 只是日历再平衡的股债混，没有 <a href="/quant/cppi-tipp">CPPI</a> 的垫。名称里的年份是营销锚，实际股权终点（to vs through retirement）差别很大。</p><h3 id="下滑不是「风险厌恶随年龄上升」一句" tabindex="-1">下滑不是「风险厌恶随年龄上升」一句 <a class="header-anchor" href="#下滑不是「风险厌恶随年龄上升」一句" aria-label="Permalink to &quot;下滑不是「风险厌恶随年龄上升」一句&quot;">​</a></h3><p>\\(\\gamma\\) 可以不变，最优股权比例仍随人力/金融财富比下降。把下滑解释成老人更怕风险，会在退休后仍有大量人力资本替代（年金、社保）时降股过猛，或在年轻高薪高相关职业降股不够。</p><p><span class="marginnote">目标日期基金的滑路径常在内部模型里优化，对外只披露滑点表。评估要用表后的实际持仓与费用，见后课费用复合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>总财富 \\(=\\) 金融 + 人力资本现值（用工资、失业率、与股市相关贴现）。对金融子组合做 Merton/BL，使总暴露接近目标。TDF 产品：用年龄当状态的一维近似，分职业风险模板。再平衡：现金流（供款）优先，减少税与费用。对照：常数混合 60/40 vs 下滑，用生命周期效用而不是单一夏普。</p><p><span class="marginnote">数字实例：25 岁新人，金融财富 50 万元、人力资本现值约 500 万元（近似一只超长久期债券）。若目标让总财富 70% 承担股权风险，金融账户需要 \\(0.7\\times 550/50=770\\%\\) 的股票权重——现实中被杠杆与产品规则截断，于是只能力所能及地高配，并随人力资本「到期」逐年降下来。</span></p><p>「总财富视角如何换算成金融账户的股债比」是一条两级链：</p>',14)),(e(),i(l,null,{default:E(()=>[n(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAGE%5B%22%E6%9C%AA%E6%9D%A5%E5%B7%A5%E8%B5%84%E7%8E%B0%E5%80%BC%22%5D%20--%3E%20HUM%5B%22%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%9C%AC%EF%BC%9A%E7%B1%BB%E5%80%BA%E5%88%B8%E4%B8%94%E4%B8%8D%E5%8F%AF%E4%BA%A4%E6%98%93%22%5D%0A%20%20OCC%5B%22%E8%81%8C%E4%B8%9A%E4%B8%8E%E8%82%A1%E5%B8%82%E7%9B%B8%E5%85%B3%E6%80%A7%22%5D%20--%3E%20HUM%0A%20%20HUM%20--%3E%20TOT%5B%22%E6%80%BB%E8%B4%A2%E5%AF%8C%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%22%5D%0A%20%20FIN%5B%22%E9%87%91%E8%9E%8D%E8%B4%A2%E5%AF%8C%22%5D%20--%3E%20TOT%0A%20%20TOT%20--%3E%20TARGET%5B%22%E7%9B%AE%E6%A0%87%E6%80%BB%E6%9A%B4%E9%9C%B2%EF%BC%88%CE%BC%20%CF%83%20%CE%B3%EF%BC%89%22%5D%0A%20%20TARGET%20--%3E%20SUB%5B%22%E9%87%91%E8%9E%8D%E5%AD%90%E7%BB%84%E5%90%88%E7%9A%84%E8%82%A1%E6%9D%83%E6%9D%83%E9%87%8D%22%5D%0A%20%20AGE%5B%22%E5%B9%B4%E9%BE%84%EF%BC%9A%E4%BA%BA%E5%8A%9B%E5%8D%A0%E6%AF%94%E9%80%90%E5%B9%B4%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20SUB%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[t("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"不可交易的债券型人力财富，要求可交易组合去做「补风险」。随时间人力债券到期（工资兑现成现金），需要卖掉一些股票以保持总风险。这就是下滑。股市与工资的正相关削弱「人力是债券」的假设，下滑应更平或更低。",-1)),(e(),i(l,null,{default:E(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Hum%5B%22%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%9C%AC%20%E4%B8%8D%E5%8F%AF%E4%BA%A4%E6%98%93%22%5D%20--%3E%20Mix%5B%22%E6%80%BB%E8%B4%A2%E5%AF%8C%E9%A3%8E%E9%99%A9%22%5D%0A%20%20Fin%5B%22%E9%87%91%E8%9E%8D%E7%BB%84%E5%90%88%22%5D%20--%3E%20Mix%0A%20%20Age%5B%22%E5%B9%B4%E9%BE%84%20%E4%BA%BA%E5%8A%9B%E5%8D%A0%E6%AF%94%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20Slide%5B%22%E8%82%A1%E6%9D%83%E4%B8%8B%E6%BB%91%22%5D%0A%20%20Corr%5B%22%E5%B7%A5%E8%B5%84%E4%B8%8E%E8%82%A1%E5%B8%82%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20Slide%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>长寿、医疗、通胀使退休后需求不是常数 \\(\\gamma\\)。TDF 的「through」路径在退休后仍持有股权，需要明确。目标日期不是保证；2008 年临退休队列的损失是路径风险，不是下滑公式算错一年。不要用 TDF 去替代个人的税与位置优化。</p><p><span class="marginnote">常见误区：把「100 减年龄」当成定理。它只是统一滑道的历史习惯式；同一出生年份的人，职业风险与积存水平天差地别。2008 年临退休的 401(k) 队列亏掉三成，说明「到点就安全」是营销话术——路径风险不会因为基金名字里写了年份就消失。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>下滑的经济学是人力资本像债券，不是年龄本身改变 \\(\\gamma\\)。</li><li>职业相关与积存水平使统一路径只是产品近似。</li><li>评估用生命周期效用与真实费用，不用单期夏普。</li><li>出处：Bodie, Merton and Samuelson, <em>JEDC</em>, 1992。</li></ul>',5))])}const f=s(p,[["render",m]]);export{c as __pageData,f as default};
